/// <summary>
/// One run of database refresh for an environment.
/// </summary>
public class BDRJobHistory extends common
{
}

Method.Source:
    public static BDRJobHistory find(RecId _recId, boolean _forUpdate = false)
    {
        BDRJobHistory jobHistory;

        if (_recId)
        {
            jobHistory.selectForUpdate(_forUpdate);

            select firstonly jobHistory
                where jobHistory.RecId == _recId;
        }

        return jobHistory;
    }

    /// <summary>
    /// Finds the job a service caller started with a request ID.
    /// </summary>
    /// <param name = "_requestId">The request ID.</param>
    /// <param name = "_environmentId">The environment; empty for any environment.</param>
    /// <returns>The job, or an empty buffer.</returns>
    public static BDRJobHistory findByRequestId(BDRRequestId _requestId, BDREnvironmentId _environmentId = '')
    {
        BDRJobHistory jobHistory;

        if (_requestId)
        {
            if (_environmentId)
            {
                select firstonly jobHistory
                    order by StartDateTime desc
                    where jobHistory.RequestId == _requestId
                        && jobHistory.EnvironmentId == _environmentId;
            }
            else
            {
                select firstonly jobHistory
                    order by StartDateTime desc
                    where jobHistory.RequestId == _requestId;
            }
        }

        return jobHistory;
    }

    /// <summary>
    /// Finds a job of the environment that is still running or waits for its batch part.
    /// Jobs older than the timeout in the parameters are left behind, for example after a restart.
    /// </summary>
    /// <param name = "_environmentId">The environment.</param>
    /// <returns>The running job, or an empty buffer.</returns>
    public static BDRJobHistory findRunning(BDREnvironmentId _environmentId)
    {
        BDRJobHistory jobHistory;
        utcdatetime since = DateTimeUtil::addHours(DateTimeUtil::utcNow(), -BDRParameters::find().jobTimeoutHours());

        select firstonly jobHistory
            where jobHistory.EnvironmentId == _environmentId
                && (jobHistory.Status == BDRJobStatus::Running || jobHistory.Status == BDRJobStatus::Scheduled)
                && jobHistory.StartDateTime > since;

        return jobHistory;
    }

    /// <summary>
    /// Deletes finished jobs older than Keep job history (days) in the parameters, with their tasks and messages.
    /// </summary>
    public static void deleteExpired()
    {
        BDRJobHistory jobHistory;
        int days = BDRParameters::find().LogRetentionDays;

        if (days <= 0)
        {
            return;
        }

        utcdatetime before = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -days);

        ttsbegin;
        delete_from jobHistory
            where jobHistory.StartDateTime < before
                && jobHistory.Status != BDRJobStatus::Running
                && jobHistory.Status != BDRJobStatus::Scheduled;
        ttscommit;
    }

    /// <summary>
    /// A running or scheduled job cannot be deleted: it still blocks new jobs of its environment.
    /// </summary>
    public boolean validateDelete()
    {
        boolean ret = super();

        if (ret && BDRJobHistory::findRunning(this.EnvironmentId).RecId == this.RecId)
        {
            ret = checkFailed(strFmt("@BDR:ErrJobRunningNoDelete", this.RecId));
        }

        return ret;
    }

/// <summary>
/// Checks whether the job has finished, including its batch part.
/// </summary>
/// <returns>True for a succeeded, partly succeeded or failed job.</returns>
public boolean isFinished()
{
    return this.RecId && this.Status != BDRJobStatus::Running && this.Status != BDRJobStatus::Scheduled && this.Status != BDRJobStatus::Waiting;
}

    /// <summary>
    /// Returns the failed tasks of the job with their messages.
    /// </summary>
    /// <returns>For example "DataCleanup (Table X is locked)".</returns>
    public str failedTasks()
    {
        BDRTaskHistory taskHistory;
        str text;

        while select TaskTypeName, Message from taskHistory
            order by Sequence
            where taskHistory.JobHistory == this.RecId
                && taskHistory.Status == BDRTaskStatus::Failed
        {
            text += (text ? '; ' : '') + (taskHistory.Message ? strFmt('%1 (%2)', taskHistory.TaskTypeName, taskHistory.Message) : taskHistory.TaskTypeName);
        }

        return subStr(text, 1, 2000);
    }
